import React, { useState, useEffect } from 'react';
import { motion, useScroll, useTransform } from 'framer-motion';
import { 
  Shield, 
  User, 
  AlertTriangle, 
  Mail, 
  Eye, 
  Search, 
  Zap, 
  CheckCircle, 
  Settings, 
  CaseSensitive, 
  Wrench, 
  MessageCircle, 
  Heart,
  ChevronDown,
  ChevronUp
} from 'lucide-react';

const slides = [
  {
    id: "slide1",
    title: "Phishing 101 - Jangan Jadi Korban!",
    content: `Belajar Mengenali dan Menghindari Serangan Phishing\n\nHampir semua orang pernah menerima email mencurigakan, tapi apakah kita yakin kita bisa membedakan mana yang asli dan palsu?`,
    animation: "fade-up",
    bg: "from-orange-500 via-orange-600 to-orange-700",
    icon: Shield
  },
  {
    id: "slide2",
    title: "Tentang Saya",
    subtitle: "Kiell Tampubolon\nInformation Security Engineer, Singapore",
    content: `Ceritakan latar belakang Anda, peran sehari-hari sebagai security engineer, pengalaman melihat berbagai serangan phishing.`,
    animation: "fade-right",
    icon: User
  },
  {
    id: "slide3",
    title: "Apa itu Phishing?",
    content: `Definisi: Teknik manipulasi sosial untuk mencuri data sensitif melalui email/pesan palsu.\nStatistik: 90% serangan dimulai dari email phishing (Verizon DBIR)\n\nBayangkan ada yang menyamar jadi petugas bank dan minta data kita. Sama, tapi dilakukan lewat email.`,
    animation: "zoom-in",
    icon: AlertTriangle
  },
  {
    id: "slide4",
    title: "Jenis-Jenis Phishing",
    points: [
      "Spear Phishing",
      "Whaling",
      "BEC (Business Email Compromise)",
      "Clone Phishing",
      "Vishing & Smishing (sekilas)"
    ],
    content: `Contoh nyata: CEO palsu minta transfer dana, atau email HR palsu minta isi form.`,
    animation: "slide-left",
    icon: Mail
  },
  {
    id: "slide5",
    title: "Ciri-Ciri Email Phishing",
    points: [
      "Alamat pengirim aneh",
      "Bahasa mendesak",
      "Link tidak sesuai",
      "File lampiran mencurigakan",
      "Tampilan mirip aslinya"
    ],
    content: `Tampilkan email palsu dan tunjukkan tiap cirinya. Bisa bandingkan dengan email asli dari bank/Gmail.`,
    animation: "fade-down",
    icon: Eye
  },
  {
    id: "slide6",
    title: "Demo - Analisis Email Phishing",
    points: [
      "VirusTotal",
      "MXToolbox",
      "Header email Gmail"
    ],
    content: `Live demo atau screenshot. Tunjukkan bagaimana menelusuri asal email dan menilai reputasi tautan.`,
    animation: "flip-up",
    icon: Search
  },
  {
    id: "slide7",
    title: "Simulasi Kirim Phishing Email",
    points: [
      "GoPhish / Template Demo",
      "Disclaimer: Edukasi saja, tidak dikirim ke peserta."
    ],
    content: `Bayangkan kalau saya kirim email dari 'admin@bank0famerica.com' — apa Anda akan percaya?`,
    animation: "zoom-out",
    icon: Zap
  },
  {
    id: "slide8",
    title: "Tips Mendeteksi Phishing",
    points: [
      "Hover sebelum klik",
      "Jangan tergesa-gesa",
      "Periksa domain/email",
      "Verifikasi ke sumber resmi"
    ],
    content: `Gunakan cerita peserta yang pernah tertipu atau hampir tertipu.`,
    animation: "fade-in",
    icon: CheckCircle
  },
  {
    id: "slide9",
    title: "Strategi Perlindungan",
    points: [
      "Untuk Individu: MFA, password manager, awareness",
      "Untuk Perusahaan: Filter email, DMARC/SPF, simulasi phishing berkala"
    ],
    content: `Tunjukkan bahwa pencegahan tidak selalu butuh teknologi mahal. Kesadaran jauh lebih penting.`,
    animation: "slide-right",
    icon: Settings
  },
  {
    id: "slide10",
    title: "Studi Kasus Nyata",
    points: [
      "BEC rugi $10 juta",
      "Phishing LinkedIn rekrutmen palsu"
    ],
    content: `Serangan ini bukan hanya ke orang awam. Bahkan eksekutif perusahaan bisa tertipu.`,
    animation: "rotate-in",
    icon: CaseSensitive
  },
  {
    id: "slide11",
    title: "Tools Gratis untuk Melindungi Diri",
    points: [
      "VirusTotal",
      "HaveIBeenPwned",
      "Password manager (Bitwarden)",
      "Email header analyzer"
    ],
    content: `Langkah kecil seperti ini bisa menyelamatkan data pribadi Anda dari pencurian.`,
    animation: "flip-left",
    icon: Wrench
  },
  {
    id: "slide12",
    title: "Tanya Jawab",
    content: `Silakan ajukan pertanyaan, bahkan yang paling sederhana. Karena hacker tidak butuh celah besar, cukup satu klik dari Anda.`,
    animation: "fade-in",
    icon: MessageCircle
  },
  {
    id: "slide13",
    title: "Penutup & CTA",
    points: [
      "Phishing bisa dicegah",
      "Edukasi & kesadaran adalah kunci",
      "Jangan klik sebelum yakin!"
    ],
    content: `Hari ini, mulai cek ulang email yang Anda terima. Jangan mudah percaya, jangan panik, selalu verifikasi.`,
    animation: "bounce-in",
    icon: Heart
  }
];

const Slide = ({ slide, isActive }) => {
  const IconComponent = slide.icon;
  
  const animationVariants = {
    "fade-up": { initial: { opacity: 0, y: 30 }, animate: { opacity: 1, y: 0 } },
    "fade-down": { initial: { opacity: 0, y: -30 }, animate: { opacity: 1, y: 0 } },
    "fade-left": { initial: { opacity: 0, x: 30 }, animate: { opacity: 1, x: 0 } },
    "fade-right": { initial: { opacity: 0, x: -30 }, animate: { opacity: 1, x: 0 } },
    "zoom-in": { initial: { opacity: 0, scale: 0.8 }, animate: { opacity: 1, scale: 1 } },
    "zoom-out": { initial: { opacity: 0, scale: 1.2 }, animate: { opacity: 1, scale: 1 } },
    "slide-left": { initial: { opacity: 0, x: 100 }, animate: { opacity: 1, x: 0 } },
    "slide-right": { initial: { opacity: 0, x: -100 }, animate: { opacity: 1, x: 0 } },
    "flip-up": { initial: { opacity: 0, rotateX: 90 }, animate: { opacity: 1, rotateX: 0 } },
    "flip-left": { initial: { opacity: 0, rotateY: 90 }, animate: { opacity: 1, rotateY: 0 } },
    "rotate-in": { initial: { opacity: 0, rotate: -180, scale: 0.8 }, animate: { opacity: 1, rotate: 0, scale: 1 } },
    "bounce-in": { initial: { opacity: 0, scale: 0.3 }, animate: { opacity: 1, scale: 1 } },
    "fade-in": { initial: { opacity: 0 }, animate: { opacity: 1 } }
  };

  const variant = animationVariants[slide.animation];

  return (
    <div className={`slide-container bg-gradient-to-br ${slide.bg || 'from-orange-500 via-orange-600 to-orange-700'}`}>
      <motion.div 
        className="slide-content"
        initial={variant.initial}
        animate={isActive ? variant.animate : variant.initial}
        transition={{ duration: 0.6, ease: "easeOut" }}
      >
        <div className="card">
          <motion.div
            initial={{ scale: 0 }}
            animate={isActive ? { scale: 1 } : { scale: 0 }}
            transition={{ delay: 0.2, duration: 0.5 }}
            className="inline-block p-4 bg-white/20 rounded-full mb-6"
          >
            <IconComponent size={48} className="text-white" />
          </motion.div>
          
          <h1 className="slide-title">{slide.title}</h1>
          
          {slide.subtitle && (
            <h2 className="slide-subtitle">{slide.subtitle}</h2>
          )}
          
          {slide.content && (
            <p className="slide-text whitespace-pre-line">{slide.content}</p>
          )}
          
          {slide.points && (
            <div className="slide-points">
              {slide.points.map((point, index) => (
                <motion.div
                  key={index}
                  className="slide-point"
                  initial={{ opacity: 0, x: -20 }}
                  animate={isActive ? { opacity: 1, x: 0 } : { opacity: 0, x: -20 }}
                  transition={{ delay: 0.3 + index * 0.1, duration: 0.5 }}
                >
                  <span className="text-2xl">{point}</span>
                </motion.div>
              ))}
            </div>
          )}
        </div>
      </motion.div>
    </div>
  );
};

const Navigation = ({ currentSlide, totalSlides, onNavigate }) => {
  return (
    <div className="fixed right-6 top-1/2 transform -translate-y-1/2 z-50 space-y-2">
      {slides.map((_, index) => (
        <button
          key={index}
          onClick={() => onNavigate(index)}
          className={`w-3 h-3 rounded-full transition-all duration-300 ${
            currentSlide === index 
              ? 'bg-white scale-125' 
              : 'bg-white/50 hover:bg-white/75'
          }`}
        />
      ))}
    </div>
  );
};

const ScrollIndicator = ({ currentSlide, totalSlides }) => {
  return (
    <div className="fixed left-6 top-1/2 transform -translate-y-1/2 z-50">
      <div className="flex flex-col items-center space-y-2">
        <ChevronUp size={20} className="text-white/50" />
        <div className="h-32 w-1 bg-white/20 rounded-full">
          <motion.div
            className="w-full bg-white rounded-full"
            initial={{ height: 0 }}
            animate={{ height: `${(currentSlide / (totalSlides - 1)) * 100}%` }}
            transition={{ duration: 0.3 }}
          />
        </div>
        <ChevronDown size={20} className="text-white/50" />
      </div>
    </div>
  );
};

function App() {
  const [currentSlide, setCurrentSlide] = useState(0);
  const { scrollYProgress } = useScroll();

  useEffect(() => {
    const handleWheel = (e) => {
      if (e.deltaY > 0 && currentSlide < slides.length - 1) {
        setCurrentSlide(prev => prev + 1);
      } else if (e.deltaY < 0 && currentSlide > 0) {
        setCurrentSlide(prev => prev - 1);
      }
    };

    const handleKeyDown = (e) => {
      if (e.key === 'ArrowDown' && currentSlide < slides.length - 1) {
        setCurrentSlide(prev => prev + 1);
      } else if (e.key === 'ArrowUp' && currentSlide > 0) {
        setCurrentSlide(prev => prev - 1);
      }
    };

    window.addEventListener('wheel', handleWheel, { passive: false });
    window.addEventListener('keydown', handleKeyDown);
    
    return () => {
      window.removeEventListener('wheel', handleWheel);
      window.removeEventListener('keydown', handleKeyDown);
    };
  }, [currentSlide]);

  useEffect(() => {
    const slideElement = document.getElementById(slides[currentSlide].id);
    if (slideElement) {
      slideElement.scrollIntoView({ behavior: 'smooth' });
    }
  }, [currentSlide]);

  return (
    <div className="relative">
      {slides.map((slide, index) => (
        <div key={slide.id} id={slide.id}>
          <Slide 
            slide={slide} 
            isActive={currentSlide === index}
          />
        </div>
      ))}
      
      <Navigation 
        currentSlide={currentSlide}
        totalSlides={slides.length}
        onNavigate={setCurrentSlide}
      />
      
      <ScrollIndicator 
        currentSlide={currentSlide}
        totalSlides={slides.length}
      />
      
      <div className="fixed bottom-6 left-1/2 transform -translate-x-1/2 z-50 text-white/70 text-sm">
        {currentSlide + 1} / {slides.length}
      </div>
    </div>
  );
}

export default App;
